<template>
  <section class="mci-cdn-cost">
    <section class="mci-cdn-cost__panel">
      <header><div><h3>云账单 · 先区分钱花在哪个产品</h3><p>CDN、OSS 公网流出、CDN 回源和 ESA 分别计费。金额来自阿里云账单，当前月尚未结算。</p></div></header>
      <div class="mci-cdn-cost__toolbar"><label>账期<input v-model="cycle" type="month"/></label><button :disabled="pending" @click="loadBills">查询产品费用</button><label>产品<select v-model="product"><option v-for="p in products" :value="p.code" :key="p.code">{{p.name}} · {{p.code}}</option></select></label><button :disabled="pending||!product" @click="loadItems(false)">查询计费项</button><button v-if="nextToken" :disabled="pending" @click="loadItems(true)">下一页计费项</button><button :disabled="pending" @click="loadPackages">查看当前资源包</button></div>
      <p class="mci-cdn-cost__hint">应付金额含实际折扣与抵扣，实付金额表示已支付。资源包当前有效列表为空不证明历史没有抵扣。</p>
      <ObservabilityTable :rows="bills" :columns="billColumns" empty-text="尚未查询账单；权限不足会明确显示，不能当作零费用"/>
      <ObservabilityTable v-if="items.length" :rows="items" :columns="itemColumns" empty-text="此页没有计费项"/>
      <ObservabilityTable v-if="packagesLoaded" :rows="packages" :columns="packageColumns" empty-text="阿里云返回当前有效资源包为空"/>
    </section>
    <section class="mci-cdn-cost__panel"><h3>OSS 存储与访问日志</h3><button :disabled="pending" @click="loadStorage">读取存储诊断</button><p class="mci-cdn-cost__hint">服务端通过公网端点读取对象可能产生 OSS 公网流出费用。内网候选需要在实际服务节点验证，不能仅按环境名称切换。</p><ObservabilityTable :rows="storage" :columns="storageColumns" empty-text="尚未读取存储端点和日志配置"/></section>
    <section class="mci-cdn-cost__panel">
      <h3>{{domain||'请选择域名'}} · 计费用量与回源效率</h3>
      <div class="mci-cdn-cost__toolbar"><label>开始时间<input v-model="start" type="datetime-local"/></label><label>结束时间<input v-model="end" type="datetime-local"/></label><label>计费地域<select v-model="area"><option v-for="a in areas" :value="a[0]" :key="a[0]">{{a[1]}}</option></select></label><label>统计间隔<select v-model.number="interval"><option :value="300">5 分钟（最多 3 天）</option><option :value="3600">1 小时（最多 7 天）</option><option :value="86400">1 天（最多 31 天）</option></select></label><button :disabled="pending||!domain" @click="loadUsage">查询计费用量</button><button :disabled="pending||!domain" @click="loadEfficiency">命中率与回源流量</button></div>
      <div v-if="usage" class="mci-cdn-cost__summary"><b>供应商计费流量 {{ bytes(usage.total) }}</b><span>{{usage.points}} 个样本 · 实际间隔 {{usage.interval}} 秒 · {{area}}</span></div>
      <p class="mci-cdn-cost__hint">总量仅汇总 Usage 的流量字节；带宽曲线的数值不用于积分推算流量或费用。缓存命中率、CDN 回源流量与 OSS 公网流出分别核对。</p>
      <ObservabilityTable :rows="metrics" :columns="metricColumns" empty-text="选择时间和地域查询真实用量"/>
    </section>
    <section class="mci-cdn-cost__panel"><h3>离线日志与实时投递状态</h3><div class="mci-cdn-cost__toolbar"><button :disabled="pending||!domain" @click="loadLogs(false)">查询所选单日的日志文件</button><button v-if="moreLogs" :disabled="pending" @click="loadLogs(true)">下一页日志</button><button :disabled="pending||!domain" @click="loadDelivery">发现现有实时日志投递</button></div><p class="mci-cdn-cost__hint">离线日志按小时生成，保留约 31 天且有延迟。此页只显示文件元数据；不展示签名下载凭证，不用于分钟级自动封禁。</p><ObservabilityTable :rows="logs" :columns="logColumns" empty-text="尚未查询或所选窗口无日志"/><pre v-if="delivery">{{delivery}}</pre></section>
    <div v-if="pending" class="mci-cdn-cost__loading" role="status">正在读取阿里云数据…</div><p v-if="error" role="alert" class="mci-cdn-cost__error">{{error}}</p>
  </section>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import ObservabilityTable from './ObservabilityTable.vue'
import {bytes,usageSummary} from '../cdn-model'
const props=defineProps({api:{type:Function,required:true},domain:{type:String,default:''}})
const local=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)
const cycle=ref(new Date().toISOString().slice(0,7)),product=ref(''),bills=ref([]),items=ref([]),packages=ref([]),packagesLoaded=ref(false),nextToken=ref(''),pending=ref(false),error=ref(''),start=ref(local(new Date(Date.now()-86400000))),end=ref(local(new Date())),area=ref('all'),interval=ref(3600),usage=ref(null),metrics=ref([]),logs=ref([]),logPage=ref(1),moreLogs=ref(false),delivery=ref('')
const areas=[['all','全部地域'],['CN','中国内地'],['OverSeas','中国内地以外'],['AP1','亚太 1'],['AP2','亚太 2'],['AP3','亚太 3'],['NA','北美'],['SA','南美'],['EU','欧洲'],['MEAA','中东非洲']]
const storage=ref([]),storageColumns=[{key:'ScopeText',label:'范围'},{key:'Bucket',label:'存储桶'},{key:'ConfiguredEndpoint',label:'当前端点'},{key:'NetworkText',label:'端点网络'},{key:'LoggingText',label:'访问日志'},{key:'SizeText',label:'存储容量'},{key:'DiagnosticError',label:'诊断异常'}]
const products=computed(()=>[...new Map(bills.value.map(x=>[x.ProductCode,{code:x.ProductCode,name:x.ProductName}])).values()])
const billColumns=[{key:'ProductName',label:'产品'},{key:'ProductDetail',label:'明细产品'},{key:'Item',label:'账单类型'},{key:'PretaxAmount',label:'应付金额'},{key:'PaymentAmount',label:'实付金额'},{key:'Currency',label:'币种'}]
const itemColumns=[{key:'BillingItem',label:'计费项'},{key:'Region',label:'地域'},{key:'Usage',label:'使用量'},{key:'UsageUnit',label:'使用量单位'},{key:'ListPrice',label:'单价'},{key:'ListPriceUnit',label:'单价单位'},{key:'DeductedByResourcePackage',label:'资源包抵扣量'},{key:'PretaxAmount',label:'应付金额'}]
const packageColumns=[{key:'InstanceId',label:'资源包'},{key:'PackageType',label:'类型'},{key:'RemainingAmount',label:'剩余'},{key:'RemainingAmountUnit',label:'单位'},{key:'ExpiryTime',label:'到期时间'}]
const metricColumns=[{key:'TimeStamp',label:'采样时间'},{key:'Metric',label:'指标'},{key:'DisplayValue',label:'数值'},{key:'DataInterval',label:'实际间隔（秒）'}],logColumns=[{key:'Name',label:'日志文件'},{key:'Size',label:'压缩体积'},{key:'StartTime',label:'开始'},{key:'EndTime',label:'结束'}]
let generation=0
watch(()=>props.domain,()=>{generation++;usage.value=null;metrics.value=[];logs.value=[];delivery.value='';moreLogs.value=false;error.value=''})
async function run(fn){if(pending.value)return;pending.value=true;error.value='';const current=generation;try{await fn(current)}catch(e){if(current===generation)error.value=e.message}finally{pending.value=false}}
function range(){const a=new Date(start.value),b=new Date(end.value);if(!Number.isFinite(+a)||!Number.isFinite(+b)||b<=a)throw Error('请选择有效的起止时间');return {StartTime:a.toISOString(),EndTime:b.toISOString(),Interval:interval.value}}
async function loadBills(){await run(async()=>{const r=await props.api('Billing',{Kind:'Overview',BillingCycle:cycle.value});bills.value=r.Result?.Items?.Item||[];if(!products.value.some(x=>x.code===product.value))product.value=products.value.find(x=>x.code==='oss')?.code||products.value[0]?.code||'';items.value=[];nextToken.value=''})}
async function loadItems(next){await run(async()=>{const r=await props.api('Billing',{Kind:'Instance',BillingCycle:cycle.value,ProductCode:product.value,Granularity:'MONTHLY',MaxResults:100,NextToken:next?nextToken.value:''});items.value=Array.isArray(r.Result?.Items)?r.Result.Items:r.Result?.Items?.Item||[];nextToken.value=r.Result?.NextToken||''})}
async function loadPackages(){await run(async()=>{const r=await props.api('Billing',{Kind:'Packages',Page:1,PageSize:100});packages.value=r.Result?.Instances?.Instance||[];packagesLoaded.value=true})}
async function loadStorage(){await run(async()=>{const r=await props.api('StorageHealth');storage.value=(r.Buckets||[]).map(x=>({...x,ScopeText:x.Scope==='Public'?'公有文件':'私有文件',NetworkText:x.ConfiguredInternal?'内网':'公网',LoggingText:x.Logging?.Success?(x.Logging.Enabled?'已开启':'未开启'):'读取失败',SizeText:x.Stat?.Success?bytes(x.Stat.StorageBytes):'未知',DiagnosticError:x.Error||[x.Logging,x.Stat].filter(v=>v&&v.Success===false).map(v=>v.CloudCode).join('；')}))})}
async function loadUsage(){await run(async g=>{const r=await props.api('Usage',{...range(),Field:'traf',UsageType:'all',DataProtocol:'all',Area:area.value});if(g!==generation)return;usage.value=usageSummary(r);metrics.value=(r.UsageDataPerInterval?.DataModule||[]).map(x=>({...x,Metric:'计费用量',DisplayValue:bytes(x.Value),DataInterval:r.DataInterval}))})}
async function loadEfficiency(){await run(async g=>{const results=await Promise.all([props.api('CacheHit',range()),props.api('OriginTraffic',range())]);if(g!==generation)return;metrics.value=results.flatMap((r,i)=>((i?r.SrcTrafficDataPerInterval?.DataModule:r.HitRateInterval?.DataModule)||[]).map(x=>({...x,Metric:i?'CDN回源流量':'流量命中率',DisplayValue:i?bytes(x.Value):`${Number(x.Value).toFixed(2)}%`,DataInterval:r.DataInterval})))})}
async function loadLogs(next){await run(async g=>{const q=range();if(Date.parse(q.EndTime)-Date.parse(q.StartTime)>86400000)throw Error('离线日志请查询不超过 24 小时的窗口');const page=next?logPage.value+1:1;const r=await props.api('Logs',{...q,Page:page,PageSize:100});if(g!==generation)return;logs.value=(r.Files||[]).map(x=>({...x,Size:bytes(x.Bytes)}));logPage.value=page;moreLogs.value=r.HasMore===true})}
async function loadDelivery(){await run(async g=>{const r=await props.api('LogDelivery');if(g===generation)delivery.value=JSON.stringify(r,null,2)})}
</script>
<style scoped>
.mci-cdn-cost{color:var(--mci-cdn-text);min-width:0}.mci-cdn-cost__panel{margin:18px 0;padding:18px;border:1px solid var(--mci-cdn-border);background:var(--mci-cdn-panel);border-radius:10px}.mci-cdn-cost h3{margin:0 0 10px;font-size:15px}.mci-cdn-cost p{color:var(--mci-cdn-muted);margin:8px 0}.mci-cdn-cost__toolbar{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin:16px 0}.mci-cdn-cost label{display:flex;flex-direction:column;gap:6px;font-size:12px}.mci-cdn-cost button,.mci-cdn-cost input,.mci-cdn-cost select{font:inherit;color:inherit;border:1px solid var(--mci-cdn-border);background:var(--mci-cdn-panel);border-radius:6px;padding:8px 11px;min-height:36px;box-sizing:border-box}.mci-cdn-cost button{display:inline-flex;align-items:center;justify-content:center;cursor:pointer}.mci-cdn-cost button:disabled{opacity:.5;cursor:not-allowed}.mci-cdn-cost button:hover:not(:disabled){border-color:var(--obs-primary)}.mci-cdn-cost :focus-visible{outline:2px solid var(--obs-primary);outline-offset:2px}.mci-cdn-cost__hint{padding:12px;background:var(--mci-cdn-bg);border-radius:6px}.mci-cdn-cost__summary{display:flex;flex-wrap:wrap;gap:20px;padding:16px;background:var(--mci-cdn-bg);font-variant-numeric:tabular-nums}.mci-cdn-cost__error{color:light-dark(#b42318,#ffb4ab)!important;position:sticky;bottom:10px;background:var(--mci-cdn-panel);padding:14px;border:1px solid var(--mci-cdn-border);border-radius:6px}.mci-cdn-cost pre{white-space:pre-wrap;overflow-wrap:anywhere}.mci-cdn-cost__loading{padding:18px;background:var(--mci-cdn-bg);border-radius:6px}@media(max-width:800px){.mci-cdn-cost__toolbar label{flex:1 1 145px}.mci-cdn-cost input,.mci-cdn-cost select{width:100%}.mci-cdn-cost__panel{padding:12px}}
</style>
